            var expected=input.Shot;var args=new object[]{expected,input.Body,input.Terrain,input.Scene,0,null};Require((bool)Static(model,"Step",args),"current Arc family has known private motor/terrain dependencies");if(finish)Static(model,"Finish",expected);
            Require(SameMotor(actual,expected),"one original projectile action equals current-input pure Arc motor before real Damage type="+actual.type+" slot="+actual.whoAmI+" native="+actual.position+"/"+actual.velocity+" expected="+expected.position+"/"+expected.velocity+" rotations="+actual.rotation.ToString("R")+"/"+expected.rotation.ToString("R")+" scales="+actual.scale.ToString("R")+"/"+expected.scale.ToString("R")+" alpha="+actual.alpha+"/"+expected.alpha+" phase="+string.Join(",",actual.localAI)+"/"+string.Join(",",expected.localAI));
            if(finish)Require(actual.timeLeft==expected.timeLeft,"native lifetime/real Kill tail agrees");motorActions++;
